CREATE OR REPLACE VIEW VW_GEO_PRATICHEINDIRIZZI AS SELECT ISTANZE.IDCOMUNE AS INSTALLAZIONE , ISTANZE.SOFTWARE AS MODULO , ISTANZE.CODICEISTANZA AS IDPRATICA , ISTANZE.NUMEROISTANZA AS NUMEROPRATICA , ISTANZE.DATA AS DATAPRATICA , VW_ALBEROPROC.SC_DESCRIZIONEPADRE AS DESCSEZIONEPRATICA , VW_ALBEROPROC.SC_CODICE AS CODTIPOPRATICA , VW_ALBEROPROC.SC_DESCRIZIONEBREVE AS DESCTIPOPRATICA , STATIISTANZA.STATO AS STATOPRATICA , RICHIEDENTI.NOMINATIVO AS RICHIEDENTE_COGNOME, RICHIEDENTI.NOME AS RICHIEDENTE_NOME, RICHIEDENTI.CODICEFISCALE AS RICHIEDENTE_CODICEFISCALE, RICHIEDENTI.PARTITAIVA AS RICHIEDENTE_PARTITAIVA, TECNICI.NOMINATIVO AS TECNICO_COGNOME, TECNICI.NOME AS TECNICO_NOME, TECNICI.CODICEFISCALE AS TECNICO_CODICEFISCALE, TECNICI.PARTITAIVA AS TECNICO_PARTITAIVA, AZIENDE.NOMINATIVO AS AZIENDA_COGNOME, AZIENDE.NOME AS AZIENDA_NOME, AZIENDE.CODICEFISCALE AS AZIENDA_CODICEFISCALE, AZIENDE.PARTITAIVA AS AZIENDA_PARTITAIVA, ISTANZESTRADARIO.ID AS IDINDIRIZZO , STRADARIO.CODVIARIO AS CODVIARIO , STRADARIO.PREFISSO AS TOPONIMO , STRADARIO.DESCRIZIONE AS DESCVIA , ISTANZESTRADARIO.CODICECIVICO AS CODICECIVICO , ISTANZESTRADARIO.CIVICO AS CIVICO , ISTANZESTRADARIO.COLORE AS COLORE , ISTANZESTRADARIO.FRAZIONE AS FRAZIONE , ISTANZESTRADARIO.CIRCOSCRIZIONE AS CIRCOSCRIZIONE , ISTANZESTRADARIO.CAP AS CAP , ISTANZESTRADARIO.KM AS KM , ISTANZESTRADARIO.ESPONENTE AS ESPONENTE , ISTANZESTRADARIO.SCALA AS SCALA , ISTANZESTRADARIO.INTERNO AS INTERNO , ISTANZESTRADARIO.ESPONENTEINTERNO AS ESPONENTEINTERNO , ISTANZESTRADARIO.FABBRICATO AS FABBRICATO , ISTANZESTRADARIO.PIANO AS PIANO , ISTANZESTRADARIO.QUARTIERE AS QUARTIERE , ISTANZESTRADARIO.ID_PUNTO_SIT AS ID_PUNTO_SIT , ISTANZESTRADARIO.UUID AS UUID , ISTANZESTRADARIO.LATITUDINE AS LATITUDINE , ISTANZESTRADARIO.LONGITUDINE AS LONGITUDINE FROM ISTANZE INNER JOIN VW_ALBEROPROC ON VW_ALBEROPROC.IDCOMUNE = ISTANZE.IDCOMUNE AND VW_ALBEROPROC.SC_ID = ISTANZE.CODICEINTERVENTOPROC INNER JOIN STATIISTANZA ON STATIISTANZA.IDCOMUNE = ISTANZE.IDCOMUNE AND STATIISTANZA.SOFTWARE = ISTANZE.SOFTWARE AND STATIISTANZA.CODICESTATO = ISTANZE.CHIUSURA INNER JOIN ANAGRAFE RICHIEDENTI ON RICHIEDENTI.IDCOMUNE = ISTANZE.IDCOMUNE AND RICHIEDENTI.CODICEANAGRAFE = ISTANZE.CODICERICHIEDENTE LEFT OUTER JOIN ANAGRAFE TECNICI ON TECNICI.IDCOMUNE = ISTANZE.IDCOMUNE AND TECNICI.CODICEANAGRAFE = ISTANZE.CODICEPROFESSIONISTA LEFT OUTER JOIN ANAGRAFE AZIENDE ON AZIENDE.IDCOMUNE = ISTANZE.IDCOMUNE AND AZIENDE.CODICEANAGRAFE = ISTANZE.CODICETITOLARELEGALE INNER JOIN ISTANZESTRADARIO ON ISTANZESTRADARIO.IDCOMUNE = ISTANZE.IDCOMUNE AND ISTANZESTRADARIO.CODICEISTANZA = ISTANZE.CODICEISTANZA INNER JOIN STRADARIO ON STRADARIO.IDCOMUNE = ISTANZESTRADARIO.IDCOMUNE AND STRADARIO.CODICESTRADARIO = ISTANZESTRADARIO.CODICESTRADARIO;
alter table DOMANDESTC modify ULTIMOERRORE varchar2(4000 CHAR);
ALTER TABLE ALBEROPROC_ENDO ADD (FLAG_RICHIESTO_BO NUMBER(1, 0));

ALTER TABLE TIPIMOVIMENTO ADD FLG_INVIALINKALLMAIL NUMBER(1,0);
ALTER TABLE TIPIMOVIMENTO ADD FLG_PROTOCOLLALINKALL NUMBER(1,0);
ALTER TABLE TIPIMOVIMENTO ADD FK_LETTTIPO_LINKALL NUMBER(10,0);

ALTER TABLE TIPIMOVIMENTO ADD CONSTRAINT FK_TIPOMOV_LETTTIPO FOREIGN KEY (IDCOMUNE,FK_LETTTIPO_LINKALL) REFERENCES LETTERETIPO (IDCOMUNE,CODICELETTERA);

CREATE TABLE TEMP_LINKALLEGATI(
UUID VARCHAR2(50 CHAR) NOT NULL, 
LINK VARCHAR2(500 CHAR) NOT NULL, 
CODICEOGGETTO NUMBER(10,0) NOT NULL, 
IDCOMUNE VARCHAR2(6 BYTE) NOT NULL, 
ID NUMBER(10,0) NOT NULL
);

   
CREATE UNIQUE INDEX TEMP_LINKALLEGATI_PK ON TEMP_LINKALLEGATI (IDCOMUNE, ID); 
ALTER TABLE TEMP_LINKALLEGATI ADD CONSTRAINT TEMP_LINKALLEGATI_PK PRIMARY KEY (IDCOMUNE, ID);

CREATE OR REPLACE FORCE VIEW VW_STATISTICHEISTANZE (F_IDCOMUNE, F_SOFTWARE, F_DATA, F_RESPONSABILE, F_PROFESSIONISTA, F_CODICEINTERVENTO, F_METRIQUADRATI, F_PROCEDURA, F_DETTAGLIOINFORMAZIONI, F_TIPOINFORMAZIONI, F_ZONIZZAZIONE, F_REGISTRO, F_STATO, CODICEISTANZA, CODICERESPONSABILE, CODICERICHIEDENTE, CODICEPROFESSIONISTA, DATA, NUMEROPROTOCOLLO, DATAPROTOCOLLO, CODICEINTERVENTO, LAVORI, CODICEPROCEDURA, CODICEAREA, CODICELOTTO, PASSWORD, ATTIVA, FOGLIO, PARTICELLA, SUB, CODICESETTORE, VARIANTEPR, CODICEIMPIANTO, CODICEATTIVITA, FLAGVIA, CHIUSURA, PROGREGAUT, LAVORIESTESA, CODICEARCHIVIO, CODICESTRADARIO, CIVICO, AUTORIZNUMERO, AUTORIZDATA, AUTORIZDATAREGISTR, AUTORIZRESPONSABILE, TIPOMOVAVVIO, TIPOARCHIVIO, CODICECOMUNE, SOFTWARE, IDMODELLO, CODICEINTERVENTOPROC, NUMEROISTANZA, IDCOMUNE, SETITOLARELEGALE, FKIDTIPOLOGIAISTANZA, CODICETITOLARELEGALE, FKTOID, METRIQUADRATI, GIORNOCHIUSURA, CODISTANZACOLLEGATA, AZIONE, FKIDREGISTRO, NOMEATTIVITA, FKIDFORMATO, POSIZIONEARCHIVIO, BASE, ALTEZZA, FACCE, FKIDPROTOCOLLO, FKCODICESOGGETTO, CODICEISTRUTTORE, CODICERESPONSABILEPROC, CODICEAREA2, FK_IDI_ATTIVITA, DATAVALIDITA, I_ATTIVITAORDINE, CREATO_DA_STC, DESCRSOGGETTO, DOMICILIO_ELETTRONICO, CODICEPRATICATEL) AS SELECT DISTINCT ISTANZE.IDCOMUNE AS f_idcomune, ISTANZE.SOFTWARE AS f_software, ISTANZE.DATA AS f_data, NVL(ISTANZE.codiceResponsabile, -1) AS f_responsabile, NVL(ISTANZE.codiceprofessionista,-1) AS f_professionista, NVL(ISTANZE.CODICEINTERVENTOPROC,ISTANZE.CODICEINTERVENTO) AS f_codiceintervento, NVL(ISTANZE.METRIQUADRATI,0) AS f_metriquadrati, NVL(ISTANZE.CODICEPROCEDURA,-1) AS f_procedura, NVL(ISTANZEATTIVITA.CodiceAttivita,' ') AS f_dettaglioinformazioni, NVL(SETTORI.CodiceSettore, -1) AS f_tipoinformazioni, NVL(ISTANZEAREE.CODICEAREA, -1) AS f_zonizzazione, NVL(AUTORIZZAZIONI.FKIDREGISTRO,-1) AS f_registro, NVL(ISTANZE.CHIUSURA,' ') AS f_stato, ISTANZE.CODICEISTANZA, ISTANZE.CODICERESPONSABILE, ISTANZE.CODICERICHIEDENTE, ISTANZE.CODICEPROFESSIONISTA, ISTANZE.DATA, ISTANZE.NUMEROPROTOCOLLO, ISTANZE.DATAPROTOCOLLO, ISTANZE.CODICEINTERVENTO, ISTANZE.LAVORI, ISTANZE.CODICEPROCEDURA, ISTANZE.CODICEAREA, ISTANZE.CODICELOTTO, ISTANZE.PASSWORD, ISTANZE.ATTIVA, ISTANZE.FOGLIO, ISTANZE.PARTICELLA, ISTANZE.SUB, ISTANZE.CODICESETTORE, ISTANZE.VARIANTEPR, ISTANZE.CODICEIMPIANTO, ISTANZE.CODICEATTIVITA, ISTANZE.FLAGVIA, ISTANZE.CHIUSURA, ISTANZE.PROGREGAUT, ISTANZE.LAVORIESTESA, ISTANZE.CODICEARCHIVIO, ISTANZE.CODICESTRADARIO, ISTANZE.CIVICO, ISTANZE.AUTORIZNUMERO, ISTANZE.AUTORIZDATA, ISTANZE.AUTORIZDATAREGISTR, ISTANZE.AUTORIZRESPONSABILE, ISTANZE.TIPOMOVAVVIO, ISTANZE.TIPOARCHIVIO, ISTANZE.CODICECOMUNE, ISTANZE.SOFTWARE, ISTANZE.IDMODELLO, ISTANZE.CODICEINTERVENTOPROC, ISTANZE.NUMEROISTANZA, ISTANZE.IDCOMUNE, ISTANZE.SETITOLARELEGALE, ISTANZE.FKIDTIPOLOGIAISTANZA, ISTANZE.CODICETITOLARELEGALE, ISTANZE.FKTOID, ISTANZE.METRIQUADRATI, ISTANZE.GIORNOCHIUSURA, ISTANZE.CODISTANZACOLLEGATA, ISTANZE.AZIONE, ISTANZE.FKIDREGISTRO, ISTANZE.NOMEATTIVITA, ISTANZE.FKIDFORMATO, ISTANZE.POSIZIONEARCHIVIO, ISTANZE.BASE, ISTANZE.ALTEZZA, ISTANZE.FACCE, ISTANZE.FKIDPROTOCOLLO, ISTANZE.FKCODICESOGGETTO, ISTANZE.CODICEISTRUTTORE, ISTANZE.CODICERESPONSABILEPROC, ISTANZE.CODICEAREA2, ISTANZE.FK_IDI_ATTIVITA, ISTANZE.DATAVALIDITA, ISTANZE.I_ATTIVITAORDINE, ISTANZE.CREATO_DA_STC, ISTANZE.DESCRSOGGETTO, ISTANZE.DOMICILIO_ELETTRONICO, ISTANZE.CODICEPRATICATEL FROM ISTANZE, ISTANZEATTIVITA, ATTIVITA, SETTORI, AUTORIZZAZIONI, ISTANZEAREE WHERE ISTANZEATTIVITA.IDCOMUNE(+) =ISTANZE.IDCOMUNE AND ISTANZEATTIVITA.CODICEISTANZA(+)=ISTANZE.CODICEISTANZA AND ATTIVITA.IDCOMUNE(+) =ISTANZEATTIVITA.IDCOMUNE AND ATTIVITA.CODICEISTAT(+) =ISTANZEATTIVITA.CODICEATTIVITA AND SETTORI.IDCOMUNE(+) =ATTIVITA.IDCOMUNE AND SETTORI.CODICESETTORE(+) =ATTIVITA.CODICESETTORE AND ISTANZEAREE.IDCOMUNE(+) = ISTANZE.IDCOMUNE AND ISTANZEAREE.CODICEISTANZA(+) = ISTANZE.CODICEISTANZA AND AUTORIZZAZIONI.IDCOMUNE(+) = ISTANZE.IDCOMUNE AND AUTORIZZAZIONI.FKIDISTANZA(+) = ISTANZE.CODICEISTANZA;
